static int checks=0;void check(bool b,const char* why){if(!b)throw std::runtime_error(why);++checks;}
QJsonObject sample(int id,QString status="completed"){return {{"id",id},{"runType","knowledge-analysis"},{"modelId","historical-model"},{"status",status},{"title","旧研究中文"+QString::number(id)},{"question","这是问题"},{"prompt","完整提示词"},{"result","完整报告 </tag> 中文\n"+QString(240000,QChar(u'长'))},{"evidence",QJsonArray{QJsonObject{{"evidenceId","原始资料"},{"quote","逐字引文"}}}},{"request",QJsonObject{{"code","600001"},{"decimal",0.1},{"negative",-0.001},{"wide",1e20}}},{"metrics",QJsonObject{{"failure",QJsonObject{{"stage","model_call"},{"message","原调用失败"}}}}},{"createdAt","2026-10-11 10:00:00"},{"updatedAt","2026-10-11 10:02:00"}};}
int main(int argc,char** argv){QApplication app(argc,argv);try{
 auto raw=sample(1);auto r=researchRuns::normalize(raw);check(r["legacyOriginal"]==raw&&r["text"]==raw["result"],"long original intact");check(!r.contains("instrumentId"),"no inferred stock identity");check(researchRuns::read(r).contains("逐字引文")&&researchRuns::read(r).contains("原调用失败"),"evidence and failure readable");
 auto completeRaw=raw;completeRaw["unknownExtension"]=QJsonObject{{"notes",QJsonArray{"未知原文",0.125}},{"link","https://example.org/a/b"}};auto completeReport=researchRuns::normalize(completeRaw);QJsonObject whole{{"version",1},{"exportedAt","2026-10-13"},{"tables",QJsonObject{{"researchRuns",QJsonArray{completeRaw}},{"expertChannels",QJsonArray{QJsonObject{{"id",999},{"unrelated",true}}}}}}};auto wholeRows=researchRuns::decode(QJsonDocument(whole).toJson());check(wholeRows==QJsonArray{completeReport},"official tables.researchRuns full record accepted");check(wholeRows[0].toObject()["legacyOriginal"]==completeRaw&&wholeRows[0].toObject()["text"]==completeRaw["result"],"envelope unknown fields and long original preserved");check(researchRuns::decode(QJsonDocument(QJsonObject{{"researchRuns",QJsonArray{raw}}}).toJson())==QJsonArray{r},"standalone old envelope remains accepted");check(researchRuns::decode(QJsonDocument(QJsonObject{{"tables",QJsonObject{{"researchRuns",QJsonArray{}}}}}).toJson()).isEmpty(),"empty official research array accepted");bool malformedEnvelope=false;try{researchRuns::decode("{\"tables\":{\"researchRuns\":{}}}");}catch(...){malformedEnvelope=true;}check(malformedEnvelope,"nonarray official research table rejected");
 auto snake=raw;snake.remove("runType");snake["run_type"]="knowledge-analysis";snake.remove("result");snake["result_text"]=raw["result"];snake.remove("evidence");snake["evidence_json"]="[{\"evidenceId\":\"旧资料\"}]";check(researchRuns::normalize(snake)["researchRun"].toObject()["evidence"].toArray().size()==1,"raw SQL mapping");
 bool bad=false;snake["evidence_json"]="broken";try{researchRuns::normalize(snake);}catch(...){bad=true;}check(bad,"malformed metadata rejected");bad=false;try{researchRuns::decode(QJsonDocument(QJsonArray{raw,raw}).toJson());}catch(...){bad=true;}check(bad,"duplicate ID rejected");
 auto mixed=raw;mixed["request"]=QJsonArray{"保留数组",0.1};mixed["metrics"]="旧文本指标";auto mixedReport=researchRuns::normalize(mixed);check(researchRuns::read(mixedReport).contains("保留数组")&&researchRuns::read(mixedReport).contains("旧文本指标"),"arbitrary old JSON metadata preserved");
 auto native=researchRuns::backup(QJsonArray{r});check(researchRuns::decode(QJsonDocument(native).toJson())==QJsonArray{r},"native backup exact roundtrip");auto corrupt=native;auto rows=corrupt["reports"].toArray();auto altered=r;altered["text"]="替换原文";rows[0]=altered;corrupt["reports"]=rows;bad=false;try{researchRuns::decode(QJsonDocument(corrupt).toJson());}catch(...){bad=true;}check(bad,"tampered backup rejected");
 auto p=researchRuns::preview(QJsonArray{r},QJsonArray{r});check(p["duplicates"].toInt()==1&&p["insert"].toArray().isEmpty(),"equal record skip");p=researchRuns::preview(QJsonArray{altered},QJsonArray{r});check(p["conflicts"].toArray().size()==1&&p["insert"].toArray().isEmpty(),"conflict retained");
 QTemporaryDir tmp;auto store=std::make_shared<BusinessStore>(tmp.filePath("local.sqlite"));auto original=store->read("reports");{ResearchRunsPage page(store);page.previewImport(QJsonDocument(QJsonArray{raw}).toJson());check(store->read("reports")==original,"preview no write");page.cancelImport();check(store->read("reports")==original,"cancel no write");page.previewImport(QJsonDocument(QJsonArray{raw}).toJson());page.confirmImport();check(store->read("reports").size()==1,"explicit merge");check(researchRuns::decode(QJsonDocument(researchRuns::backup(store->read("reports"))).toJson())==store->read("reports"),"actual Store updatedAt export strictly accepted");check(researchRuns::preview(QJsonArray{r},store->read("reports"))["duplicates"].toInt()==1,"local save timestamp does not create false conflict");auto list=page.findChild<QListWidget*>("researchRunsList");list->setCurrentRow(0);check(page.findChild<QPlainTextEdit*>("researchRunsOriginal")->toPlainText().contains(raw["result"].toString()),"native full reader");}
 {ResearchRunsPage reopened(store);check(reopened.findChild<QPlainTextEdit*>("researchRunsOriginal")->toPlainText().contains("完整提示词"),"reopen selection reader");reopened.previewImport(QJsonDocument(QJsonArray{sample(2)}).toJson());store->save("reports",{{"title","其他报告"},{"text","未覆盖"}});reopened.confirmImport();check(store->read("reports").size()==2,"stale preview blocks all inserts");}
 auto before=store->read("reports");bad=false;try{store->mergeResearchReports(QJsonArray{r},before);}catch(...){bad=true;}check(bad&&store->read("reports")==before,"duplicate transaction rollback");
 auto invalid=researchRuns::normalize(sample(301));invalid["title"]="";bad=false;try{store->mergeResearchReports(QJsonArray{researchRuns::normalize(sample(300)),invalid},before);}catch(...){bad=true;}check(bad&&store->read("reports")==before,"late validation failure rolls back earlier insert");
 QJsonArray many;for(int i=1;i<=123;i++){auto s=sample(i);s["result"]="行";many.append(researchRuns::normalize(s));}check(researchRuns::filter(many,"","","","")[0].toObject()["id"]=="legacy-research:123","numeric old ID descending order");store->mergeResearchReports(researchRuns::preview(many,before)["insert"].toArray(),before);ResearchRunsPage paged(store);check(paged.findChild<QListWidget*>("researchRunsList")->count()==50,"page first 50");paged.findChild<QPushButton*>("researchRunsNext")->click();check(paged.findChild<QListWidget*>("researchRunsList")->count()==50,"second page");paged.findChild<QPushButton*>("researchRunsNext")->click();check(paged.findChild<QListWidget*>("researchRunsList")->count()==23,"final page includes all");
 QString dbPath=tmp.filePath("old.sqlite");{auto db=QSqlDatabase::addDatabase("QSQLITE","rrfixture");db.setDatabaseName(dbPath);check(db.open(),"fixture opens");QSqlQuery q(db);check(q.exec("CREATE TABLE ai_research_runs(id INTEGER,run_type TEXT,model_id TEXT,status TEXT,title TEXT,result_text TEXT,evidence_json TEXT,request_json TEXT,metrics_json TEXT)"),"old schema");check(q.exec("INSERT INTO ai_research_runs VALUES(9,'knowledge-analysis','old','failed','失败原文','旧报告','[]','{}','{\"failure\":{\"message\":\"原失败\"}}')"),"old fixture");check(q.exec("CREATE TABLE portfolio_accounts(id INTEGER,name TEXT,cash_balance REAL)"),"old account compatibility table");check(q.exec("CREATE TABLE trades(id INTEGER,trade_date TEXT)"),"old trades compatibility table");db.close();}QSqlDatabase::removeDatabase("rrfixture");QFile oldFile(dbPath);oldFile.open(QIODevice::ReadOnly);auto oldHash=QCryptographicHash::hash(oldFile.readAll(),QCryptographicHash::Sha256);oldFile.close();auto imported=legacydata::readResearchRuns(dbPath);check(imported["reports"].toArray().size()==1&&imported["reports"].toArray()[0].toObject()["researchRun"].toObject()["status"]=="failed","readonly SQLite conversion");auto businessImport=legacydata::readBusiness(dbPath);check(businessImport["reports"].toArray().size()==1,"existing business conversion includes research runs");oldFile.open(QIODevice::ReadOnly);check(oldHash==QCryptographicHash::hash(oldFile.readAll(),QCryptographicHash::Sha256),"old database unchanged");
 {auto pendingStore=std::make_shared<BusinessStore>(tmp.filePath("pending.sqlite"));{ResearchRunsPage prepared(pendingStore);prepared.previewImport(QJsonDocument(QJsonArray{raw}).toJson());}ResearchRunsPage restored(pendingStore);check(restored.findChild<QPushButton*>("researchRunsConfirm")->isEnabled(),"pending preview restored");restored.confirmImport();check(pendingStore->read("reports").size()==1,"reopened preview explicit merge");}
 auto emptyPending=researchRuns::normalize(QJsonObject{{"id",501},{"runType","knowledge-analysis"},{"modelId","old"},{"status","pending"}});check(researchRuns::read(emptyPending).contains("旧运行未结束"),"pending stays unfinished");
 if(argc>2){QFile cross(QString::fromLocal8Bit(argv[2]));check(cross.open(QIODevice::ReadOnly),"Java fixture readable");check(researchRuns::decode(cross.readAll())==QJsonArray{r},"Java export returns to Qt with all fields");}
 if(argc>1){QFile cross(QString::fromLocal8Bit(argv[1]));check(cross.open(QIODevice::WriteOnly),"cross fixture output");cross.write(QJsonDocument(native).toJson());}
 std::cout<<"research runs Qt: "<<checks<<" checks GREEN\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
